class Refusal(Exception): pass
class Deadline(Exception): pass

def need(value,code):
    if not value:raise Refusal(code)

def digest(raw):return hashlib.sha256(raw).hexdigest()
def canonical(value):return (json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False)+'\n').encode('ascii')
def token(raw,pattern):
    value=raw.decode('ascii','strict').strip();need(re.fullmatch(pattern,value) is not None,'TOKEN_SHAPE_REFUSED');return value

def read_regular(path,maximum=1024*1024):
    path=Path(path);before=path.lstat()
    def mark(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns,s.st_uid,s.st_gid)
    need(stat.S_ISREG(before.st_mode) and before.st_nlink==1 and 0<=before.st_size<=maximum,'ORDINARY_BOUNDED_FILE_REQUIRED')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    try:
        need(mark(os.fstat(fd))==mark(before) and not os.listxattr(fd),'FILE_OPEN_CHANGED')
        with os.fdopen(fd,'rb',closefd=False) as stream:raw=stream.read(maximum+1)
        need(len(raw)==before.st_size and mark(os.fstat(fd))==mark(before) and mark(path.lstat())==mark(before),'FILE_CAPTURE_CHANGED')
        return raw
    finally:os.close(fd)

def validate_boot_identity(raw):
    need(type(raw) is bytes and re.fullmatch(
        rb'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\n',raw) is not None,
        'BOOT_ID_VALUE_REFUSED')
    return raw

def read_boot_identity():
    """Read this one procfs value without treating its reported size as bytes.

    Ordinary-file custody above is unchanged. The fixed kernel file must report
    size zero, remain the same ordinary root-owned procfs object, and return the
    same canonical UUID plus LF twice through the held descriptor.
    """
    path=Path('/proc/sys/kernel/random/boot_id')
    def mark(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_uid,s.st_gid)
    for parent in reversed(path.parents):
        info=parent.lstat()
        need(stat.S_ISDIR(info.st_mode) and not stat.S_ISLNK(info.st_mode)
             and info.st_uid==0 and not info.st_mode&0o022,'BOOT_ID_ANCESTRY_REFUSED')
    before=path.lstat()
    need(stat.S_ISREG(before.st_mode) and before.st_nlink==1 and before.st_size==0
         and before.st_uid==before.st_gid==0 and stat.S_IMODE(before.st_mode)==0o444,
         'BOOT_ID_PROCFS_SHAPE_REFUSED')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    try:
        need(mark(os.fstat(fd))==mark(before),'BOOT_ID_OPEN_CHANGED')
        first=validate_boot_identity(os.read(fd,129))
        need(os.lseek(fd,0,os.SEEK_SET)==0,'BOOT_ID_REWIND_REFUSED')
        second=os.read(fd,129)
        need(first==second and mark(os.fstat(fd))==mark(before)
             and mark(path.lstat())==mark(before),'BOOT_ID_READBACK_CHANGED')
        return first
    finally:os.close(fd)

def parse_json(raw):
    def pairs(values):
        result={}
        for key,value in values:
            need(key not in result,'DUPLICATE_JSON_KEY');result[key]=value
        return result
    return json.loads(raw,object_pairs_hook=pairs,parse_constant=lambda _:(_ for _ in ()).throw(Refusal('NONFINITE_JSON')))

def load_module(name):
    need(name in MODULE_PINS, 'MODULE_SELECTION_REFUSED')
    path = Path(__file__).with_name(name + '.py')
    raw = read_regular(path, 1024 * 1024)
    need(digest(raw) == MODULE_PINS[name], 'MODULE_PIN_REFUSED')
    module = types.ModuleType('g1_hosted_' + name)
    module.__file__ = str(path)
    if name in ('native_prerequisite', 'host_composition', 'natural_inputs'):
        module._HOST_EVIDENCE_IO = load_module('evidence_io')
    if name == 'host_composition':
        module._ROOT_PLACEMENT = load_module('root_placement')
    exec(compile(raw, str(path), 'exec'), module.__dict__)
    need(read_regular(path, 1024 * 1024) == raw, 'MODULE_CHANGED_DURING_LOAD')
    return module

def require_complete_packet():
    expected = {'host_utility', 'operation', 'provider_layout', 'source_store', 'input_setup',
                'native_prerequisite', 'nss_configuration', 'g3_receiving', 'evidence_io',
                'native_probe', 'host_composition', 'natural_inputs', 'root_placement', 'proof_consumer'}
    need(set(MODULE_PINS) == expected, 'PACKET_MODULE_POPULATION_REFUSED')
    for name, pin in MODULE_PINS.items():
        need(type(pin) is str and re.fullmatch('[0-9a-f]{64}', pin), 'G3_INTEGRATION_NOT_SEALED')
        need(digest(read_regular(Path(__file__).with_name(name + '.py'), 1024 * 1024)) == pin,
             'PACKET_MODULE_PIN_REFUSED')
    need(set(G3_DATA_PINS) == {'ORIGINAL_SCOPE.json', 'ADVERSE_APPLICABILITY.json',
         'HOST_COMPOSITION.json', 'NATIVE_SOURCE_APPLICABILITY.json', 'INDEPENDENT_PROOF_PINS.json'}, 'G3_DATA_POPULATION_REFUSED')
    for name, pin in G3_DATA_PINS.items():
        need(digest(read_regular(Path(__file__).with_name(name), 1024 * 1024)) == pin, 'G3_DATA_PIN_REFUSED')

def identities(path):
    p=Path(path); st=p.lstat();need(stat.S_ISDIR(st.st_mode) and not p.is_symlink(),'DIRECTORY_CUSTODY_REFUSED')
    return [st.st_dev,st.st_ino,st.st_uid]

def runtime_snapshot(source,state,u):
    run=state['run_root'];need(re.fullmatch(r'\.IMPLEMENTAUDIT/runs/[a-z0-9][a-z0-9-]*-[A-Za-z0-9]{6}',run),'RUN_ROOT_SHAPE_REFUSED')
    base=source/'.IMPLEMENTAUDIT'; expected={'.r36-locks/namespace.gate'}
    prefix=run.removeprefix('.IMPLEMENTAUDIT/')+'/'
    expected.update(prefix+n for n in (*NAMES,'phases/phase-1.md','.claimed','.controller'))
    observed={};directories=set();total=0
    for parent,dirs,files in os.walk(base,followlinks=False):
        here=Path(parent);st=here.lstat();need(stat.S_ISDIR(st.st_mode) and st.st_uid==os.geteuid() and not here.is_symlink(),'RUNTIME_DIRECTORY_REFUSED')
        directories.add(here.relative_to(base).as_posix())
        for name in dirs:need(not (here/name).is_symlink(),'RUNTIME_SYMLINK_REFUSED')
        for name in files:
            p=here/name;rel=p.relative_to(base).as_posix();st=p.lstat();need(rel in expected and st.st_uid==os.geteuid(),'RUNTIME_POPULATION_REFUSED')
            canonical_member=rel.startswith(prefix) and rel[len(prefix):] in (*NAMES,'phases/phase-1.md')
            raw=u.checked_file(p,PRIVATE_CANONICAL_BYTES if canonical_member else 65536);total+=len(raw);need(total<=512*1024,'RUNTIME_AGGREGATE_BOUND')
            observed[rel]={'bytes':len(raw),'sha256':digest(raw),'device':st.st_dev,'inode':st.st_ino}
    expected_dirs={'.','.r36-locks','runs',run.removeprefix('.IMPLEMENTAUDIT/'),run.removeprefix('.IMPLEMENTAUDIT/')+'/phases'}
    need(set(observed)==expected and directories==expected_dirs,'RUNTIME_POPULATION_REFUSED')
    need(observed['.r36-locks/namespace.gate']['bytes']==1,'RUNTIME_GATE_SHAPE_REFUSED')
    return observed

def write_private(path,raw):
    need(not path.exists(),'PRIVATE_MEMBER_ALREADY_EXISTS')
    with path.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    os.chmod(path,0o600)

def save_state(path,state):
    tmp=path.with_suffix('.next');need(not tmp.exists(),'STATE_WRITE_INTERRUPTED')
    with tmp.open('xb') as f:f.write(canonical(state));f.flush();os.fsync(f.fileno())
    os.chmod(tmp,0o600);os.replace(tmp,path)

def enable_subreaper():
    lib=ctypes.CDLL(None,use_errno=True);actual=ctypes.c_int()
    need(lib.prctl(36,1,0,0,0)==0 and lib.prctl(37,ctypes.byref(actual),0,0,0)==0 and actual.value==1,'SUBREAPER_REFUSED')


def manifest():
    raw=read_regular(Path(__file__).with_name('SOURCE_MANIFEST.json'),1024*1024)
    need(digest(raw)==MANIFEST_SHA,'MANIFEST_PIN_REFUSED');value=parse_json(raw)
    need(value.get('schema')=='dg16.inner-owner.cumulative-source-candidate.v1' and value.get('commit')==SOURCE_COMMIT
         and value.get('parent_commit')==SOURCE_PARENT and value.get('tree')==SOURCE_TREE
         and value.get('file_count')==SOURCE_FILES and value.get('total_bytes')==SOURCE_BYTES,'MANIFEST_SUBJECT_REFUSED')
    members={}
    for row in value['members']:
        need(type(row) is dict and set(row)=={'path','mode','git_blob','bytes','sha256'},'MANIFEST_MEMBER_SHAPE')
        path=PurePosixPath(row['path'])
        need(not path.is_absolute() and '..' not in path.parts and str(path)==row['path']
             and row['path'] not in members and row['mode'] in ('100644','100755')
             and type(row['bytes']) is int and 0<=row['bytes']<=128*1024**2
             and re.fullmatch('[0-9a-f]{40}',row['git_blob']) and re.fullmatch('[0-9a-f]{64}',row['sha256']),
             'MANIFEST_MEMBER_REFUSED')
        members[row['path']]=row
    need(len(members)==SOURCE_FILES and sum(r['bytes'] for r in members.values())==SOURCE_BYTES,'MANIFEST_POPULATION_REFUSED')
    return members

def verify_source(source,members,runtime=False):
    observed=set();total=0
    allowed={str(p) for name in members for p in PurePosixPath(name).parents if str(p)!='.'}
    for parent,dirs,files in os.walk(source,followlinks=False):
        here=Path(parent);info=here.lstat()
        need(stat.S_ISDIR(info.st_mode) and info.st_uid==info.st_gid==0
             and not info.st_mode&0o022,'SOURCE_DIRECTORY_CUSTODY_REFUSED')
        for name in list(dirs):
            path=here/name;relative=path.relative_to(source).as_posix();info=path.lstat()
            need(stat.S_ISDIR(info.st_mode) and not path.is_symlink(),'SOURCE_DIRECTORY_REFUSED')
            if here==source and name=='.git':dirs.remove(name)
            elif here==source and name=='.IMPLEMENTAUDIT':
                need(runtime,'PREEXISTING_RUNTIME_REFUSED');dirs.remove(name)
            else:need(relative in allowed,'UNEXPECTED_SOURCE_DIRECTORY')
        for name in files:
            path=here/name;relative=path.relative_to(source).as_posix()
            need(relative in members,'UNEXPECTED_SOURCE_FILE');row=members[relative];info=path.lstat()
            need(info.st_uid==info.st_gid==0 and stat.S_IMODE(info.st_mode)==(0o755 if row['mode']=='100755' else 0o644),
                 'SOURCE_FILE_MODE_REFUSED')
            raw=read_regular(path,128*1024**2)
            need(len(raw)==row['bytes'] and digest(raw)==row['sha256']
                 and hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==row['git_blob'],'SOURCE_BYTES_REFUSED')
            observed.add(relative);total+=len(raw)
    need(observed==set(members) and total==SOURCE_BYTES,'SOURCE_POPULATION_REFUSED')
    return dict(file_count=len(observed),total_bytes=total,manifest_sha256=MANIFEST_SHA,all_members_match=True)

def whole_source_census(source):
    """Preserve the complete ordinary-source envelope before provider effects."""
    rows=[];total=0
    for parent,dirs,files in os.walk(source,followlinks=False):
        for name in dirs+files:
            path=Path(parent)/name;relative=path.relative_to(source);info=path.lstat()
            need(len(relative.parts)<=40 and len(rows)<4096,'SOURCE_CENSUS_TOPOLOGY_BOUND')
            need(not path.is_symlink() and (stat.S_ISDIR(info.st_mode) or stat.S_ISREG(info.st_mode)),
                 'SOURCE_CENSUS_TYPE_REFUSED')
            row=dict(path=relative.as_posix(),mode=stat.S_IMODE(info.st_mode),kind='DIRECTORY' if stat.S_ISDIR(info.st_mode) else 'FILE')
            if stat.S_ISREG(info.st_mode):
                raw=read_regular(path,128*1024**2);total+=len(raw)
                need(total<=256*1024**2,'SOURCE_CENSUS_TOTAL_BOUND');row.update(bytes=len(raw),sha256=digest(raw))
            rows.append(row)
    return dict(files=sum(r['kind']=='FILE' for r in rows),entries=len(rows),bytes=total,population_sha256=digest(canonical(rows)),
                scope='ALL_ACTUAL_ORDINARY_SOURCE_GIT_AND_HIDDEN_ENTRIES_NO_OMISSIONS')

def host_context(output, source):
    e = os.environ
    need(e.get('GITHUB_ACTIONS') == 'true' and e.get('GITHUB_REPOSITORY') == REPOSITORY
         and e.get('GITHUB_EVENT_NAME') == 'push' and e.get('GITHUB_REF') == 'refs/heads/' + BRANCH
         and e.get('GITHUB_RUN_ATTEMPT') == '1' and e.get('RUNNER_ENVIRONMENT') == 'github-hosted', 'EVENT_GUARD_REFUSED')
    run = e.get('GITHUB_RUN_ID', '')
    workflow = e.get('GITHUB_SHA', '')
    need(re.fullmatch('[0-9]{1,20}', run) and re.fullmatch('[0-9a-f]{40}', workflow), 'HOSTED_IDENTITY_REFUSED')
    context = dict(repository=REPOSITORY, branch=BRANCH, run_id=run, run_attempt=1, workflow_commit=workflow,
                   workspace=str(Path(e['GITHUB_WORKSPACE']).resolve(strict=True)),
                   runner_temp=str(Path(e['RUNNER_TEMP']).resolve(strict=True)))
    composition = load_module('host_composition')
    wanted = composition.paths(composition.binding(), context)
    need(wanted == dict(source=source, private_output=output, packet=Path(__file__).absolute().parent),
         'RESOURCE_SCOPE_REFUSED')
    return context

def configure_descriptor_capacity(state,state_path,step):
    """Establish the declared 4096 soft capacity in this one adapter process.

    A distinct sudo/Python invocation inherits its own limit. The original
    product gate stays unchanged; this prospective host configuration never
    raises or lowers the observed hard limit and expires with this process.
    """
    before=resource.getrlimit(resource.RLIMIT_NOFILE)
    need(type(before) is tuple and len(before)==2
         and all(type(v) is int and v>=-1 for v in before),'DESCRIPTOR_LIMIT_SHAPE_REFUSED')
    rows=state.setdefault('descriptor_configurations',[])
    need(step in (*STEPS,'finalize') and len(rows)<len(STEPS)+1
         and all(row['step']!=step for row in rows),'DESCRIPTOR_CONFIGURATION_SEQUENCE_REFUSED')
    row=dict(step=step,resource='RLIMIT_NOFILE',target_soft=4096,before=list(before),
        attempted=False,set_returned=False,after=None,hard_unchanged=None,established=False)
    rows.append(row);save_state(state_path,state)
    try:
        need(before[1]==resource.RLIM_INFINITY or before[1]>=4096,
             'DECLARED_DESCRIPTOR_HARD_CAPACITY_UNAVAILABLE')
        if before[0]!=4096:
            row['attempted']=True;save_state(state_path,state)
            resource.setrlimit(resource.RLIMIT_NOFILE,(4096,before[1]))
            row['set_returned']=True
    finally:
        # Read the actual result even after a refused set; never infer its state
        # from an exception. A missing readback remains unknown and fails closed.
        try:
            after=resource.getrlimit(resource.RLIMIT_NOFILE)
            need(type(after) is tuple and len(after)==2
                 and all(type(v) is int and v>=-1 for v in after),'DESCRIPTOR_LIMIT_SHAPE_REFUSED')
            row['after']=list(after)
            row['hard_unchanged']=after[1]==before[1]
            row['established']=after==(4096,before[1])
        finally:
            save_state(state_path,state)
    need(row['established'] and row['hard_unchanged'],'DESCRIPTOR_CONFIGURATION_READBACK_REFUSED')

def descriptor_configuration_public(state):
    rows=state.get('descriptor_configurations',[])
    need(type(rows) is list and len(rows)<=len(STEPS)+1,'DESCRIPTOR_PUBLIC_POPULATION_REFUSED')
    result=[];seen=set()
    for row in rows:
        need(type(row) is dict and set(row)=={'step','resource','target_soft','before',
            'attempted','set_returned','after','hard_unchanged','established'}
            and row['step'] in (*STEPS,'finalize') and row['step'] not in seen
            and row['resource']=='RLIMIT_NOFILE' and type(row['target_soft']) is int
            and row['target_soft']==4096,'DESCRIPTOR_PUBLIC_ROW_REFUSED')
        seen.add(row['step'])
        for key in ('before','after'):
            value=row[key]
            need(key=='after' and value is None or type(value) is list and len(value)==2
                 and all(type(v) is int and -1<=v<=2**63-1 for v in value),
                 'DESCRIPTOR_PUBLIC_LIMIT_REFUSED')
        need(all(type(row[key]) is bool for key in ('attempted','set_returned','established'))
             and (row['hard_unchanged'] is None or type(row['hard_unchanged']) is bool),
             'DESCRIPTOR_PUBLIC_FLAG_REFUSED')
        after=row['after'];before=row['before']
        need(row['hard_unchanged'] is (None if after is None else after[1]==before[1])
             and row['established'] is (after==[4096,before[1]])
             and (not row['set_returned'] or row['attempted']),
             'DESCRIPTOR_PUBLIC_RELATION_REFUSED')
        result.append(dict(row,before=['UNLIMITED' if v==-1 else v for v in before],
            after=None if after is None else ['UNLIMITED' if v==-1 else v for v in after]))
    return dict(schema='dg16.g1-hosted-descriptor-configuration.v1',
        scope='THIS_ADAPTER_PROCESS_AND_DESCENDANTS_ONLY',target_soft=4096,
        original_product_limit_unchanged=True,hard_limit_may_change=False,
        no_system_configuration_or_ownership_change=True,rows=result)

def inventory(state,u):
    facts=dict(uid=os.getuid(),euid=os.geteuid(),gid=os.getgid(),egid=os.getegid(),
        architecture=os.uname().machine,kernel=os.uname().release,python_version=list(sys.version_info[:3]),
        image_os=os.environ.get('ImageOS',''),image_version=os.environ.get('ImageVersion',''),tools={},
        descriptor_limits=list(resource.getrlimit(resource.RLIMIT_NOFILE)))
    state['host_observations'].append(facts)
    release={}
    for line in read_regular(Path('/etc/os-release').resolve(),16384).decode().splitlines():
        if '=' in line:
            key,value=line.split('=',1)
            if key in ('ID','VERSION_ID'):release[key]=value.strip('"')
    facts['os']=release;facts['boot_identity_sha256']=digest(read_boot_identity())
    paths={}
    for name in ('python3.12','git','bash','bwrap'):
        paths[name],facts['tools'][name]=u.trusted(name)
    need(sys.platform=='linux' and facts['architecture']=='x86_64'
         and facts['uid']==facts['euid']==facts['gid']==facts['egid']==0,'HOST_IDENTITY_REFUSED')
    need(release=={'ID':'ubuntu','VERSION_ID':'24.04'} and facts['python_version']==[3,12,3]
         and facts['image_os']=='ubuntu24' and facts['image_version']=='20261101.360.1','HOST_PROFILE_CHANGED')
    need(all(paths[name] is not None for name in ('python3.12','git','bash')),'TRUSTED_TOOL_UNAVAILABLE')
    need(facts['descriptor_limits'][0]>=4096,'DECLARED_DESCRIPTOR_CAPACITY_UNAVAILABLE')
    need(Path(sys.executable).resolve()==Path(paths['python3.12'])
         and facts['tools']['python3.12']['sha256']=='e50d468e8b0adfb05733f5b87b3cff34829c4a8c1aea50c865aa8bdfe4bb150f'
         and facts['tools']['git']['sha256']=='824d5b2fffef332ec7ba053e579659bb12f26a0b4747da6f9c6dc0e71d36f235','SELECTED_TOOL_BYTES_CHANGED')
    if paths['bwrap'] is not None:
        need(facts['tools']['bwrap']['sha256']=='52231e1caf55bcbc667b269f49c63599a6f7db4767ae6a039580d0ff853db712','LAUNCHER_BYTES_CHANGED')
    return paths

def git_identity(source,command,full=False):
    rc,out,err=command('source-identity',['/usr/bin/git','-C',str(source),'show','-s','--format=%H%n%T%n%P','HEAD'])
    need(rc==0 and not err and out.decode().splitlines()==[SOURCE_COMMIT,SOURCE_TREE,SOURCE_PARENT],'SOURCE_GIT_IDENTITY_REFUSED')
    if full:
        for label,args in (('index-clean',['diff','--cached','--quiet','--exit-code']),('tracked-clean',['diff','--quiet','--exit-code'])):
            rc,out,err=command(label,['/usr/bin/git','-C',str(source),*args]);need(rc==0 and not out and not err,'SOURCE_TRACKED_STATE_CHANGED')

def prepare_source(state,source,private,command):
    need(not source.exists() and not source.is_symlink(),'FRESH_SOURCE_REQUIRED')
    def git(label,args,seconds=60):
        rc,out,err=command(label,['/usr/bin/git','-c','protocol.https.allow=always',*args],seconds=seconds)
        need(rc==0,'ORDINARY_GIT_PREPARATION_REFUSED');return out
    git('ordinary-clone',['clone','--quiet','--no-local','--no-hardlinks','--no-checkout','--',
        'https://github.com/'+REPOSITORY+'.git',str(source)],seconds=180)
    state['source_directory_identity']=identities(source);state['git_directory_identity']=identities(source/'.git')
    branch=token(git('clone-default-branch',['-C',str(source),'symbolic-ref','--short','HEAD']),r'[A-Za-z0-9][A-Za-z0-9._/-]{0,127}')
    tracking=git('clone-actual-tracking',['-C',str(source),'config','--local','--get-regexp',r'^branch\.']).decode().splitlines()
    need(len(tracking)==2 and set(tracking)=={'branch.'+branch+'.remote origin','branch.'+branch+'.merge refs/heads/'+branch},'CLONE_TRACKING_SECTION_REFUSED')
    git('remove-observed-new-tracking',['-C',str(source),'config','--local','--remove-section','branch.'+branch])
    git('fetch-selected-commit',['-c','maintenance.autoDetach=false','-C',str(source),'fetch','--quiet','--no-tags','--no-recurse-submodules','origin',SOURCE_COMMIT],seconds=120)
    git('detach-selected-commit',['-C',str(source),'checkout','--quiet','--detach',SOURCE_COMMIT],seconds=60)
    git_identity(source,command,True)
    need(git('complete-clone',['-C',str(source),'rev-parse','--is-shallow-repository'])==b'false\n','SHALLOW_SOURCE_REFUSED')
    need(not git('new-clone-clean',['-C',str(source),'status','--porcelain=v1','--untracked-files=all','--ignored']),'FRESH_SOURCE_DIRTY')
    git('complete-object-check',['-C',str(source),'fsck','--strict','--full','--no-dangling'],seconds=120)
    # --quiet suppresses listing only; --missing=error still refuses incomplete
    # reachable objects. The maintained source owner reacquires all actual bytes.
    git('missing-object-check',['-C',str(source),'rev-list','--objects','--all','--missing=error','--quiet'],seconds=60)
    need(not git('no-imported-controller-refs',['-C',str(source),'for-each-ref','--format=%(refname)','refs/implementaudit']),
         'IMPORTED_CONTROLLER_REFS_REFUSED')
    store=load_module('source_store')
    state['loose_head']=store.retain_actual_head(source,private,SOURCE_COMMIT,SOURCE_TREE,command,read_regular,write_private)
    state['source_before']=verify_source(source,manifest(),False)
    state['source_census_before']=whole_source_census(source)
    need(digest(read_regular(source/SETUP,1024*1024))==SETUP_SHA,'SETUP_OWNER_PIN_REFUSED')

def fresh_state(context,output):
    now=time.monotonic()
    return dict(schema='dg16.g1-hosted-private-episode.v1',context=context,controller='r5-g1-hosted-'+context['run_id']+'-a1',
        run_root=None,receipt=None,completed=[],failed=False,failures=[],reads={},runtime=None,commands=[],host_observations=[],
        started_monotonic=now,deadline_monotonic=now+RUN_SECONDS,output_directory_identity=identities(output),
        source_directory_identity=None,git_directory_identity=None,source_before=None,source_after=None,
        source_unchanged=False,runtime_unchanged=False,all_step_children_reaped=True,
        active_step=None,interrupted_step=None,prior_step_children_unknown=False,policy_attempted=False,
        policy_finalized=False,nss_configuration_attempted=False,nss_configuration=None,nss_configuration_final=None,
        provider_started=False,provider_prepared=False,operation_started=False,
        operation_result=None,operation_received=False,g3_prepared=False,g3_received=False,
        g3_original_received=False,public_eligible=False)

def require_current(state,source,command,private,label):
    rc,out,err=command(label,['/usr/bin/bash',str(source/OWNER),'--require-current-continuity',state['controller']],seconds=30)
    need(rc==0 and out.decode().strip()==state['receipt'],'CURRENTNESS_REFUSED')
    return digest(out)

def owner(state,source,command,label,args):
    rc,out,err=command(label,['/usr/bin/bash',str(source/OWNER),*args],seconds=60)
    need(rc==0,'MAINTAINED_OWNER_REFUSED');return out

def native_step(step,state,source,output,command,u):
    controller=state['controller'];private=output/'private'
    if step=='initialize':
        raw=owner(state,source,command,'fresh-claim',['--controller',controller,'r5-g1-hosted'])
        run=token(raw,r'\.IMPLEMENTAUDIT/runs/r5-g1-hosted-[A-Za-z0-9]{6}');state['run_root']=run
        rc,out,err=command('author-real-task',['/usr/bin/python3.12','-I','-S','-B',str(source/AUTHOR),
            '--repo',str(source),'--run-root',run,'--source',str(source),'--purpose',PURPOSE,'--next-action',NEXT_ACTION])
        need(rc==0,'REAL_TASK_AUTHOR_REFUSED');value=parse_json(out)
        need(type(value) is dict and set(value)==set((*NAMES,'phases/phase-1.md')),'AUTHOR_POPULATION_REFUSED')
        for name,sha in value.items():need(digest(read_regular(source/run/name,PRIVATE_CANONICAL_BYTES))==sha,'AUTHORED_READBACK_REFUSED')
        # The exact reviewed G3 author adds native fences before activation.
        g3=load_module('g3_receiving');g3.author_checkpoint(g3_api(state,source,output,command))
        inspected=parse_json(owner(state,source,command,'inspect-initialization',['--inspect-controller-initialization',controller,'--run-root',run]))
        init=inspected['initialization_token']
        need(type(init) is str and re.fullmatch('refs/implementaudit/controller-initializations/'+controller+r'/[0-9a-f]{32}@[0-9a-f]{40}',init),'INITIALIZATION_TOKEN_REFUSED')
        activated=parse_json(owner(state,source,command,'activate-initialization',['--activate-controller',controller,'--run-root',run,'--expected-initialization',init]))
        need(activated.get('status')=='BOUND_ELIGIBLE_FOR_NORMAL_CURRENTNESS'
             and activated.get('authority_ceiling')=='ELIGIBLE_FOR_NORMAL_CURRENTNESS_ONLY','ACTIVATION_SCOPE_REFUSED')
        state['runtime']=runtime_snapshot(source,state,u);state['initialization_sha256']=digest(canonical(activated))
    elif step=='discover':
        raw=owner(state,source,command,'discover-controller',['--current-controller',controller]);parts=raw.decode().strip().split('\t')
        need(len(parts)==4 and parts[0]==controller and Path(parts[1])==source
             and Path(parts[2])==source/state['run_root'],'CONTROLLER_CONTEXT_REFUSED')
    elif step=='invalidate':
        event='github-run-'+state['context']['run_id']+'-attempt-1-g1-fresh-hosted-job'
        raw=owner(state,source,command,'invalidate-new-session',['--invalidate-continuity',controller,'--boundary','new-session','--event',event])
        state['invalidation']=token(raw,'refs/implementaudit/continuity-invalidations/'+controller+r'@[0-9a-f]{40}')
    elif step in ('read-state','read-roadmap'):
        name='STATE.md' if step=='read-state' else 'ROADMAP.md';raw=read_regular(source/state['run_root']/name,PRIVATE_CANONICAL_BYTES)
        write_private(private/(step+'.read'),raw)
        state['reads'][name]=dict(bytes=len(raw),sha256=digest(raw),step_ordinal=len(state['completed'])+1)
        if step=='read-roadmap':need(state['reads']['STATE.md']['step_ordinal']<state['reads'][name]['step_ordinal'],'SEPARATE_READ_ORDER_REFUSED')
    elif step=='resume':
        need(set(state['reads'])=={'STATE.md','ROADMAP.md'},'CANONICAL_READS_REQUIRED')
        for name,row in state['reads'].items():need(digest(read_regular(source/state['run_root']/name,PRIVATE_CANONICAL_BYTES))==row['sha256'],'READ_BYTES_CHANGED')
        raw=owner(state,source,command,'resume-new-session',['--resume-controller',controller,'--boundary','new-session','--epoch','G0001'])
        state['receipt']=token(raw,'refs/implementaudit/continuity-receipts/'+controller+r'/G0001@[0-9a-f]{40}')
    elif step=='verify':
        raw=owner(state,source,command,'verify-resume',['--verify-resume-receipt',state['receipt']])
        need(raw.decode().strip()==state['receipt'],'VERIFIED_RECEIPT_DIFFERS')
    elif step=='require':state['first_currentness_sha256']=require_current(state,source,command,private,'initial-currentness')
    else:raise Refusal('UNKNOWN_NATIVE_STEP')

KNOWN_FAILURE_CODES += ('INDEPENDENT_PROOF_CONSUMER_REFUSED',)

def independent_consumer_inputs():
    consumer=load_module('proof_consumer')
    root=Path(__file__).resolve().parent
    pins_raw=read_regular(root/'INDEPENDENT_PROOF_PINS.json',8192)
    scope_raw=read_regular(root/'ORIGINAL_SCOPE.json',65536)
    need(digest(pins_raw)==G3_DATA_PINS['INDEPENDENT_PROOF_PINS.json']
         and digest(scope_raw)==G3_DATA_PINS['ORIGINAL_SCOPE.json'],'INDEPENDENT_PROOF_CONSUMER_REFUSED')
    pins=consumer.pins_contract(consumer.parse(pins_raw,canonical=True,maximum=8192))
    return consumer,pins,consumer.parse(scope_raw,canonical=True,maximum=65536)

def consume_independent_proofs(actual_api):
    consumer,pins,_=independent_consumer_inputs()
    try:return consumer.execute(actual_api,pins)
    except consumer.Refusal as exc:raise Refusal('INDEPENDENT_PROOF_CONSUMER_REFUSED') from exc

def g3_api(state, source, output, command):
    return dict(source=source, run_root=state['run_root'], controller=state['controller'], receipt=state['receipt'],
        private=output / 'private', command=command, deadline_monotonic=state['deadline_monotonic'],
        require_current=lambda label: require_current(state, source, command, output / 'private', label),
        read_regular=read_regular, write_private=write_private,
        independent_proof_consumer=consume_independent_proofs,
        verify_g1_retained=lambda: verify_g1_retained(state, source, output, command),
        verify_g1_selected_inputs=lambda: verify_g1_selected_inputs(state, source, output, command),
        verify_native_prerequisite=lambda *, current=True: verify_native_prerequisite(state, source, output, command, current=current))

def nss_preflight(state,source,output,command,prefix):
    need(prefix in ('early','prerequisite'),'NSS_RECORD_PREFIX_REFUSED')
    private=output/'private';op=load_module('operation')
    require_current(state,source,command,private,prefix+'-nss-currentness')
    engine=op.load_selected(source);objects={}
    captured={name:engine.B.capture_selector(name,objects,limit=65536) for name in ('/etc/passwd','/etc/nsswitch.conf')}
    for name,row in captured.items():
        need(row['kind']=='FILE','NSS_FILE_CAPTURE_REFUSED');write_private(private/(prefix+'-'+Path(name).name+'.raw'),objects[row['sha256']])
    observation=op.nss_token_observation(objects[captured['/etc/nsswitch.conf']['sha256']])
    write_private(private/(prefix+'-NSS_OBSERVATION.json'),canonical(observation));state['nss_observation']=observation
    nscd={name:engine.B.capture_selector(name,objects) for name in engine.B._NSCD}
    engine.D._validate_nss(dict(files=captured,nscd=nscd),objects);engine.CHECK()
    return engine

def prerequisites(state,source,output,command):
    private=output/'private';setup=load_module('input_setup')
