    # No provider is consumed until actual unchanged files-only NSS admission.
    setup._COMMAND_DEADLINE=state['deadline_monotonic'];setup._UTILITY=load_module('host_utility')
    setup.root_ancestry(Path('/usr/bin/python3.12'));setup.root_ancestry(Path('/usr/bin/git'))
